#include "SkillLaborRuntime.hpp"
namespace elysium::citizens {bool SkillLaborRuntime::setSkills(StableId id,std::vector<SkillState>s){if(!id)return false;skills_[id]=std::move(s);return true;}void SkillLaborRuntime::setWorkDetail(StableId id,std::unordered_set<ContentId>w){work_[id]=std::move(w);}Eligibility SkillLaborRuntime::eligible(StableId id,ContentId skill,ContentId family,std::uint32_t req,EffectiveSkillContext c)const{auto wi=work_.find(id);if(wi!=work_.end()&&!wi->second.empty()&&!wi->second.count(family))return{false,0,"work detail disabled"};auto si=skills_.find(id);if(si==skills_.end())return{req==0,0,req?"missing skill":""};double rank=0;for(auto&s:si->second)if(s.skill==skill)rank=s.rank;auto finite=[](double v){return std::isfinite(v)?v:0.0;};double eff=std::max(0.0,rank*std::max(0.0,finite(c.focus))*std::max(0.0,finite(c.injury))*std::max(0.0,finite(c.tool))*std::max(0.0,finite(c.environment))*std::max(0.0,finite(c.mentorship))*std::max(0.0,finite(c.passive)));return{eff>=req,eff,eff>=req?"":"effective skill below requirement"};}bool SkillLaborRuntime::practice(StableId id,ContentId skill,double base,double diminishing){auto i=skills_.find(id);if(i==skills_.end())return false;for(auto&s:i->second)if(s.skill==skill){double gain=std::max(0.0,base)/(1.0+std::max(0.0,diminishing)*s.rank);s.xp+=gain;while(s.xp>=100.0){s.xp-=100.0;++s.rank;}return true;}return false;}}
